<?php
require_once 'connection/config.php';
require_once '__init.php';
require_once 'inc/functions.php';
require_once 'inc/Auth.php';
require_once 'inc/ParentWeeklyReport.php';
require_once 'inc/RecoveryPlanTemplates.php';

$conn = db();
$base = rtrim((string) $baseUrl, '/');
$escape = static fn($value): string => htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8');
$courses = mmh_parent_report_courses($conn);
$courseId = trim((string) ($_GET['course_id'] ?? ''));
$templateId = (int) ($_GET['template_id'] ?? 0);
$search = trim((string) ($_GET['q'] ?? ''));
if ($courseId === '' && $templateId > 0) {
    $candidate = mmh_recovery_template_load($conn, $templateId);
    $courseId = (string) ($candidate['course_id'] ?? '');
}
if ($courseId === '') $courseId = (string) ($courses[0]['course_id'] ?? '');
$templates = $courseId !== '' ? mmh_recovery_template_list($conn, $courseId, true) : [];
foreach ($templates as &$templateSummary) $templateSummary['id'] = (int) $templateSummary['id'];
unset($templateSummary);
if ($templateId <= 0 && $templates) $templateId = (int) $templates[0]['id'];
$template = $templateId > 0 ? mmh_recovery_template_load($conn, $templateId) : null;
if ($template && (string) $template['course_id'] !== $courseId) { $courseId = (string) $template['course_id']; $templates = mmh_recovery_template_list($conn, $courseId, true); foreach ($templates as &$templateSummary) $templateSummary['id'] = (int) $templateSummary['id']; unset($templateSummary); }
$students = ($template && $template['status'] !== 'archived') ? mmh_recovery_template_students($conn, (string) $template['course_id'], $search) : [];
$assignments = [];
if ($template) {
    $stmt = $conn->prepare('SELECT a.id, a.student_id, a.status, a.assigned_at, a.started_at, a.completed_at, p.id AS plan_id, p.status AS plan_status, u.full_name, u.username FROM recovery_plan_assignments a INNER JOIN users u ON u.user_id = a.student_id LEFT JOIN recovery_plans p ON p.id = a.plan_id WHERE a.template_id = ? ORDER BY u.full_name ASC, u.username ASC');
    if ($stmt) { $stmt->bind_param('i', $templateId); $stmt->execute(); $assignments = $stmt->get_result()->fetch_all(MYSQLI_ASSOC); $stmt->close(); }
}
$assignmentByStudent = [];
foreach ($assignments as $assignment) $assignmentByStudent[(int) $assignment['student_id']] = $assignment;
$counts = ['assigned' => 0, 'in_progress' => 0, 'completed' => 0];
foreach ($assignments as $assignment) { $status = (string) ($assignment['status'] ?? 'assigned'); if (isset($counts[$status])) $counts[$status]++; }
$assignedTotal = count($assignments); $completedTotal = $counts['completed'];
$averageMinutes = null;
foreach ($templates as $templateSummary) if ((int) $templateSummary['id'] === $templateId) { $averageMinutes = $templateSummary['average_completion_minutes'] ?? null; break; }
$flash = $_SESSION['recovery_assignment_flash'] ?? null; unset($_SESSION['recovery_assignment_flash']);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Recovery Plan Assignments | <?= $escape($site_name ?? 'Math Mastery Hub') ?></title><?php include 'layouts/admin/header.php'; ?><style>
.assignment-admin{max-width:1280px;margin-top:55px;padding:24px}.assignment-card{padding:18px;margin-bottom:16px;border:1px solid var(--border);border-radius:var(--radius-lg);background:var(--surface);box-shadow:var(--shadow-sm)}.assignment-toolbar,.assignment-actions{display:flex;gap:10px;align-items:end;flex-wrap:wrap}.assignment-toolbar label{display:grid;gap:5px;color:var(--text-muted);font-size:.78rem;font-weight:700;min-width:220px}.assignment-stats{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px;margin-top:14px}.assignment-stat{padding:12px;border:1px solid var(--border);border-radius:var(--radius-md);background:var(--surface-elevated)}.assignment-stat strong{display:block;font-size:1.2rem;color:var(--text-primary)}.assignment-stat span{font-size:.76rem;color:var(--text-muted)}.assignment-table{width:100%;border-collapse:collapse}.assignment-table th,.assignment-table td{padding:10px 8px;border-bottom:1px solid var(--border);text-align:left;vertical-align:middle}.assignment-table th{font-size:.76rem;color:var(--text-muted);text-transform:uppercase;letter-spacing:.04em}.assignment-status{font-size:.78rem;font-weight:700;color:var(--text-secondary)}.assignment-status.completed{color:var(--success)}.assignment-status.in_progress{color:var(--warning)}@media(max-width:800px){.assignment-admin{padding:14px}.assignment-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.assignment-table{display:block;overflow-x:auto;white-space:nowrap}}
</style></head><body class="dash ds-bg-primary"><div class="col-12 d-flex"><?php include 'layouts/admin/aside.php'; ?><div class="main-content in-active"><?php include 'layouts/admin/top-nav.php'; ?><main class="assignment-admin"><section class="assignment-card"><div class="assignment-toolbar"><div><p class="course-manager-eyebrow">Student support</p><h1 class="h3 mb-1">Recovery Plan Assignments</h1><p class="template-help mb-0">Assign independent copies of a reusable template. Existing student plans are never reset.</p></div><form method="get" action="<?= $escape($base . '/admin/recovery-plan-assignments') ?>"><label>Course<select class="form-control" name="course_id" onchange="this.form.submit()"><?php foreach ($courses as $course): ?><option value="<?= $escape($course['course_id']) ?>" <?= $courseId === (string) $course['course_id'] ? 'selected' : '' ?>><?= $escape($course['course_title']) ?></option><?php endforeach; ?></select></label></form><form method="get" action="<?= $escape($base . '/admin/recovery-plan-assignments') ?>"><input type="hidden" name="course_id" value="<?= $escape($courseId) ?>"><label>Template<select class="form-control" name="template_id" onchange="this.form.submit()"><?php foreach ($templates as $candidate): ?><option value="<?= (int) $candidate['id'] ?>" <?= $templateId === (int) $candidate['id'] ? 'selected' : '' ?>><?= $escape($candidate['title']) ?><?= $candidate['status'] === 'archived' ? ' (Archived)' : '' ?></option><?php endforeach; ?></select></label></form></div><?php if (is_array($flash)): ?><div class="alert alert-<?= !empty($flash['ok']) ? 'success' : 'danger' ?> mt-3"><?= $escape($flash['message'] ?? '') ?></div><?php endif; ?><?php if ($template): ?><div class="assignment-stats"><div class="assignment-stat"><strong><?= $assignedTotal ?></strong><span>Assigned students</span></div><div class="assignment-stat"><strong><?= $counts['assigned'] ?></strong><span>Not started</span></div><div class="assignment-stat"><strong><?= $counts['in_progress'] ?></strong><span>In progress</span></div><div class="assignment-stat"><strong><?= $counts['completed'] ?></strong><span>Completed</span></div><div class="assignment-stat"><strong><?= $assignedTotal > 0 ? round(($completedTotal / $assignedTotal) * 100) : 0 ?>%</strong><span>Completion · <?= $escape((string) (($templates[array_search($templateId, array_column($templates, 'id'), true)]['average_completion_minutes'] ?? '') ?: '—')) ?> min avg</span></div></div><?php endif; ?></section><?php if (!$template): ?><section class="assignment-card"><p class="template-help mb-0">Create a template first, then return here to assign it.</p></section><?php elseif ($template['status'] === 'archived'): ?><section class="assignment-card"><p class="template-help mb-0">This template is archived and cannot be assigned. Duplicate it to create a new active template.</p></section><?php else: ?><section class="assignment-card"><form method="get" action="<?= $escape($base . '/admin/recovery-plan-assignments') ?>" class="assignment-toolbar mb-3"><input type="hidden" name="course_id" value="<?= $escape($courseId) ?>"><input type="hidden" name="template_id" value="<?= $templateId ?>"><label>Search enrolled students<input class="form-control" type="search" name="q" value="<?= $escape($search) ?>" placeholder="Name or username"></label><button class="btn btn-outline-secondary" type="submit">Search</button></form><form method="post" action="<?= $escape($base . '/admin/requests/recovery-plan-template/assign') ?>"><input type="hidden" name="_token" value="<?= $escape(mmh_auth_csrf_token()) ?>"><input type="hidden" name="template_id" value="<?= $templateId ?>"><div class="assignment-actions mb-3"><label><input type="checkbox" name="assign_course" value="1"> Assign to all enrolled students</label><button class="btn btn-primary" type="submit">Assign selected students</button><a class="btn btn-outline-secondary" href="<?= $escape($base . '/admin/recovery-plan-templates?course_id=' . rawurlencode($courseId) . '&template_id=' . $templateId) ?>">Edit template</a></div><div class="table-responsive"><table class="assignment-table"><thead><tr><th><span class="visually-hidden">Select</span></th><th>Student</th><th>Assignment status</th><th>Assigned</th><th>Completed</th></tr></thead><tbody><?php foreach ($students as $student): $studentId = (int) $student['user_id']; $assignment = $assignmentByStudent[$studentId] ?? null; $status = (string) ($assignment['status'] ?? 'Not assigned'); ?><tr><td><input type="checkbox" name="student_ids[]" value="<?= $studentId ?>" <?= $assignment ? 'disabled' : '' ?> aria-label="Select <?= $escape($student['full_name'] ?: $student['username']) ?>"></td><td><strong><?= $escape($student['full_name'] ?: $student['username']) ?></strong><small class="d-block text-muted"><?= $escape($student['username']) ?></small></td><td class="assignment-status <?= $escape(str_replace(' ', '_', strtolower($status))) ?>"><?= $escape(ucwords(str_replace('_', ' ', $status))) ?></td><td><?= $assignment ? $escape(date('j M Y', strtotime((string) $assignment['assigned_at']))) : '—' ?></td><td><?= !empty($assignment['completed_at']) ? $escape(date('j M Y', strtotime((string) $assignment['completed_at']))) : '—' ?></td></tr><?php endforeach; ?><?php if (!$students): ?><tr><td colspan="5" class="template-help">No enrolled students match this search.</td></tr><?php endif; ?></tbody></table></div></form></section><?php endif; ?></main></div></div></body></html>
